import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Count outputs (executed actions) and inputs (opponent executed actions)
    my_c = 0
    my_d = 0
    op_c = 0
    op_d = 0
    for me, opp in history:
        if me == 'C':
            my_c += 1
        else:
            my_d += 1
        if opp == 'C':
            op_c += 1
        else:
            op_d += 1

    opp_coop_rate = op_c / n
    my_coop_rate = my_c / n

    # Detect opponent patterns from their last few moves
    last_ops = [opp for _, opp in history[-12:]]
    # Are they always the same?
    all_c = all(x == 'C' for x in last_ops)
    all_d = all(x == 'D' for x in last_ops)
    # Runs of D
    run_d = 0
    for x in reversed(last_ops):
        if x == 'D':
            run_d += 1
        else:
            break
    run_c = 0
    for x in reversed(last_ops):
        if x == 'C':
            run_c += 1
        else:
            break

    # Detect simple periodicity (period 2,3,4) in opponent history
    period = 0
    if n >= 6:
        for p in (2, 3, 4):
            if n >= 2 * p + 2:
                seg = [opp for _, opp in history[-p:]]
                prev = [opp for _, opp in history[-2 * p:-p]]
                if seg == prev:
                    period = p
                    break

    last_me, last_op = history[-1]

    # Score-based: if opponent mostly cooperates, cooperate to extract CC=3.
    # If opponent is mostly defecting, defect to avoid CD=0, take DD=1.
    if opp_coop_rate >= 0.85:
        return 'C'
    if opp_coop_rate <= 0.15:
        return 'D'

    # Conditionally retaliate: if opponent just defected, defect once in reply
    if last_op == 'D' and run_d == 1:
        # one-shot punishment
        return 'D'

    # If opponent has long D streak, keep defecting
    if run_d >= 2:
        return 'D'

    # If we are at a fairly cooperative state, cooperate.
    if opp_coop_rate >= 0.55:
        # Slightly protect: if our coop rate very high and opp dropped once, still C
        return 'C'

    # Mid/lower coop: use limited probing and defection pressure
    # If opponent pattern periodic, predict next and reciprocate optimally
    if period:
        # next opponent move based on periodic pattern
        idx = n % period
        # history index of last period start
        recent = [opp for _, opp in history[n - period:]]
        predicted = recent[idx % period] if period else 'D'
        if predicted == 'C':
            # if predicted C, sometimes take DC=5 if they might not retaliate heavily
            if opp_coop_rate < 0.75 and my_coop_rate < 0.8 and (n % 5 == 0):
                return 'D'
            return 'C'
        else:
            return 'D'

    # Default: mixed responsive with slight optimization
    # Early rounds: test cooperation
    if n < 4:
        return 'C'

    # Compute expected values for C vs D given opp coop rate and likely reaction
    # If opponent coop rate moderate, try exploit when it looks safe
    if opp_coop_rate >= 0.35 and opp_coop_rate < 0.6:
        # Alternate exploiting and cooperating to avoid pure punishment
        if n % 4 == 0:
            return 'D'
        return 'C'

    # Very low coop: defect
    if opp_coop_rate < 0.35:
        return 'D'

    return 'C'

